package app.xiaohe.tests;
import android.content.Context;import org.json.*;import app.xiaohe.assistant.*;import java.util.*;
public final class FinalSmoke {
  public static void run(Store db,Context context)throws Exception {
    MemoryLedger ledger=new MemoryLedger(db);JSONObject tasks=ledger.page(new JSONObject().put("tasksOnly",true).put("status","active").put("limit",40));if(tasks.getInt("total")<200||tasks.getJSONArray("rows").length()!=40||!tasks.getBoolean("hasMore"))throw new AssertionError("Task pagination must expose all tasks beyond cache");for(int i=0;i<tasks.getJSONArray("rows").length();i++){JSONObject r=tasks.getJSONArray("rows").getJSONObject(i);if(!Arrays.asList("event","task").contains(r.optString("type"))||!r.optString("status").equals("active"))throw new AssertionError("Task page filters status/type");}JSONObject later=ledger.page(new JSONObject().put("tasksOnly",true).put("status","active").put("limit",40).put("offset",200));if(later.getJSONArray("rows").length()!=40)throw new AssertionError("Older tasks cannot disappear at cache boundary");
    JSONObject m=db.message("user","之前和朋友见过面",new JSONArray(),UUID.randomUUID().toString());JSONObject r=new JSONObject().put("id",UUID.randomUUID().toString()).put("created",m.getLong("created")).put("sourceId",m.getString("id")).put("type","event").put("kind","event").put("eventState","occurred").put("status","active").put("content","之前和朋友见过面").put("time",TimeAnchor.resolve("之前",m,false,null));db.put("memories",r);JSONObject confirmed=ledger.confirmTime(r.getString("id"),"2026-09-08");if(!confirmed.getJSONObject("time").optString("raw").equals("之前")||!confirmed.getJSONObject("time").optBoolean("confirmedByUser"))throw new AssertionError("Confirming date must retain original relative wording");if(ledger.history(r.getString("id")).length()!=2)throw new AssertionError("Date confirmation adds a version");
    JSONObject blocked=new JSONObject(r.toString()).put("id",UUID.randomUUID().toString()).put("truthState","disputed").put("remindAt",System.currentTimeMillis()+1500);db.put("memories",blocked);Scheduler.set(context,blocked);Thread.sleep(2400);if(db.one("memories",blocked.getString("id")).optBoolean("reminderFired"))throw new AssertionError("Unconfirmed contradictory memory must not schedule automatic reminder");
    if(ledger.search("同事小林现在的咖啡偏好",10,m).length()==0)throw new AssertionError("Current fact still available after pagination change");
  }
}
